// ===================== 陽間站崗 A／B 批美術（art/cut_stn_ab.py 由 gen_art/gb_chibi_sheet2.png、gb_vfx_sheet.png 自動切圖生成，唔好手改）=====================
// pb_sq_*：網紅組／探險組專屬造型；pb_guide／pb_ghostclub／pb_walkdel／pb_hawker：新路人；vfx_*：設備特效。全部透明 webp，角色高 300px、腳底置中。
// 喺 sprites.js 之後載入，所以自己 new Image 一次＋decode（同 SPR 共用），唔會重複載入。
const STN_AB_SRC = {
  pb_sq_host:'data:image/webp;base64,',
  pb_sq_cam:'data:image/webp;base64,',
  pb_sq_aide:'data:image/webp;base64,',
  pb_sq_live:'data:image/webp;base64,',
  pb_sq_lead:'data:image/webp;base64,',
  pb_sq_vcam:'data:image/webp;base64,',
  pb_sq_torch:'data:image/webp;base64,',
  pb_sq_sound:'data:image/webp;base64,',
  pb_guide:'data:image/webp;base64,',
  pb_ghostclub:'data:image/webp;base64,',
  pb_walkdel:'data:image/webp;base64,',
  pb_hawker:'data:image/webp;base64,',
  vfx_ghost_rise:'data:image/webp;base64,',
  vfx_ghost_lunge:'data:image/webp;base64,',
  vfx_ghost_smoke:'data:image/webp;base64,',
  vfx_hand_crack:'data:image/webp;base64,',
  vfx_mist_ring:'data:image/webp;base64,',
  vfx_water_hands:'data:image/webp;base64,',
  vfx_frost:'data:image/webp;base64,',
  vfx_seal:'data:image/webp;base64,',
};
const STN_AB_NOLEG = { pb_sq_live:1, pb_hawker:1 }; // 有道具喺地（腳架、手推車）：唔分腳，只係上下彈＋左右擺
(() => { if (typeof SPR === 'undefined') return; if (typeof SPR_SRC !== 'undefined') Object.assign(SPR_SRC, STN_AB_SRC);
  for (const k in STN_AB_SRC) { if (SPR[k]) continue; const im = new Image(); im.src = STN_AB_SRC[k]; SPR[k] = im; const ok = () => { im._ok = true; }; if (im.decode) im.decode().then(ok, () => { im.onload = ok; }); else im.onload = ok; } })();
